# Debates: key topics; entries: (side, kind, author, body, [verses (book_id, ch, v, v_end)], [refs])
DEBATES = [
 dict(title="Does free will exist alongside divine sovereignty?", cat="theology",
  question="Can human beings be genuinely free and morally responsible if God exercises meticulous sovereignty over history?",
  summary="Christians across traditions affirm both that God is sovereign and that people are responsible for their choices. They disagree sharply on how these fit together.",
  aff="Compatible", opp="Incompatible (in the libertarian sense)",
  aff_sum="Freedom and divine sovereignty fit together: freedom means acting from one's own motives without coercion, and God's governance works through, not against, those motives.",
  opp_sum="Responsibility requires that agents could have done otherwise. A God who determines all outcomes would remove that capacity, so sovereignty must be understood more modestly.",
  entries=[
   ("aff", "opening", "rachel_kim", "Scripture presents both truths side by side without apology. Joseph's brothers meant evil against him, and God meant it for good (Genesis 50:20). The same event is fully the brothers' act and fully within God's plan. The compatibilist account explains this: a free act is one that flows from the agent's own desires and reasons, not from external compulsion. God can ordain ends through means that include real human choosing. This is the position of the Westminster Confession (3.1, 9.1), and it was also held by Jonathan Edwards, who argued that the will is always determined by the strongest motive, and that this is what freedom amounts to.", [(0, 50, 20, None), (43, 2, 23, None), (44, 9, 19, 21)], ["Westminster Confession of Faith, chs. 3 and 9", "Edwards, J. (1754). Freedom of the Will", "Frankfurt, H. (1969). 'Alternate Possibilities and Moral Responsibility', Journal of Philosophy 66"]),
   ("opp", "opening", "thomas_ashby", "Moral responsibility seems to require that a person could have chosen otherwise. If every choice is determined by prior causes ultimately traceable to God's decree, I do not see how the agent can be the ultimate source of the act. Scripture repeatedly addresses humans as able to respond to real alternatives: 'choose this day whom you will serve' (Joshua 24:15). Many Christians, from the early Fathers through Arminius and today's Molinists, hold that God can govern the world and achieve his purposes while granting creatures the genuine power of contrary choice. Plantinga's free will defense also shows why a world with real freedom is a good that God might permit.", [(5, 24, 15, None), (39, 23, 37, None), (60, 3, 9, None)], ["Plantinga, A. (1974). God, Freedom, and Evil", "van Inwagen, P. (1983). An Essay on Free Will", "Craig, W. L. (2001). The Only Wise God (on middle knowledge)"]),
   ("aff", "rebuttal", "rachel_kim", "The 'could have done otherwise' requirement is not as obvious as it seems. Frankfurt-style cases suggest a person can be responsible for an act even when they could not have avoided it, if they acted for their own reasons. Further, libertarian freedom introduces its own problem: if my choice is not determined by my character and reasons, it looks random, not free. I would also point out that Scripture does not hide divine initiative: 'It is God who works in you, both to will and to work for his good pleasure' (Philippians 2:13). We must make sense of this, not set it aside.", [(49, 2, 12, 13)], ["Frankfurt (1969), cited above", "Strawson, G. (1994). 'The Impossibility of Moral Responsibility', Philosophical Studies 75"]),
   ("opp", "rebuttal", "thomas_ashby", "Frankfurt cases remain controversial, and critics argue that they smuggle in assumptions. The randomness objection also has replies: agent-causal accounts hold that the agent, not a prior event, is the source of the choice. As for Philippians 2:13, God's working in us is compatible with God enabling rather than determining. I would add that the compatibilist account faces the problem of evil in a sharper form: if God ordains every desire, it is hard to say how he is not the author of sin, however much the Confession insists he is not.", [(49, 2, 13, None)], ["Chisholm, R. (1964). 'Human Freedom and the Self'", "Fischer, J. M. (1994). The Metaphysics of Free Will"]),
   ("aff", "counter", "sofia_marin", "A neutral observation both sides should face: popular claims that neuroscience has 'disproved free will' (often citing Libet's 1983 experiments) are overstated. Later work, for instance Schurger et al. (2012), reinterprets the readiness potential as spontaneous neural fluctuation rather than an unconscious decision. Neither of the positions above depends on those experiments, and neither is refuted by them.", [], ["Libet, B. et al. (1983). Brain 106", "Schurger, A., Sitt, J. & Dehaene, S. (2012). PNAS 109"]),
  ]),
 dict(title="Is human nature fundamentally sinful?", cat="human-nature",
  question="Is the human condition best described as fundamentally corrupted by sin, or as fundamentally good (made in God's image) but damaged and in need of restoration?",
  summary="Christian traditions agree that humanity is created good and in need of salvation, but differ on how deeply sin has affected human nature and how to read the evidence from psychology.",
  aff="Fundamentally sinful (total depravity)", opp="Fundamentally good, but wounded",
  aff_sum="Sin affects every part of human nature from birth, so the human heart is not merely disposed to wrongdoing but turned away from God.",
  opp_sum="The image of God remains the deepest truth about persons; sin is a distortion that has not abolished human goodness, dignity or moral capacity.",
  entries=[
   ("aff", "opening", "rachel_kim", "Scripture makes universal claims: 'all have sinned and fall short of the glory of God' (Romans 3:23); 'I was brought forth in iniquity' (Psalm 51:5); 'the heart is deceitful above all things' (Jeremiah 17:9). The Reformed doctrine of total depravity is often misunderstood: it does not mean everyone is as bad as possible, but that sin corrupts every faculty, including the mind and will, so that no one can come to God unaided. Augustine argued that this condition is inherited from Adam. The universality of cruelty, self-deception and moral failure across cultures is consistent with that picture.", [(44, 3, 23, None), (18, 51, 5, None), (23, 17, 9, None), (48, 2, 1, 3)], ["Augustine, On the Spirit and the Letter; Enchiridion", "Calvin, Institutes II.1-3", "Canons of Dort, Third and Fourth Heads"]),
   ("opp", "opening", "marcus_bell", "Genesis 1 declares humanity 'very good', and the image of God is never withdrawn: James 3:9 still speaks of people 'made in the likeness of God', and Genesis 9:6 grounds the prohibition against murder in it. Eastern Christianity speaks of ancestral sin rather than inherited guilt, and emphasizes healing of a wounded nature rather than a nature that is intrinsically bad. Developmental research is suggestive: studies of infants (Hamlin, Wynn and Bloom, 2007) find preferences for helpful agents. I would hold that evidence loosely, but it fits the view that humans are made for goodness and can often do it, even while sin is real and pervasive.", [(0, 1, 31, None), (0, 9, 6, None), (58, 3, 9, None)], ["Hamlin, J. K., Wynn, K. & Bloom, P. (2007). Nature 450", "Ware, K. (1995). The Orthodox Way", "Bloom, P. (2013). Just Babies"]),
   ("aff", "rebuttal", "rachel_kim", "I appreciate the emphasis on the image of God, and the Reformed tradition affirms it fully. The claim is not that people lack dignity but that the Fall has affected every aspect of our nature. As for infant studies, they are interesting but they cannot adjudicate a theological question, and the same literature also documents in-group bias very early. Paul's argument in Romans 1-3 is that all, Jew and Gentile, are under sin, which is why the gospel is good news for everyone.", [(44, 5, 12, 19)], ["Hamlin et al. (2007), cited above", "Stott, J. (1994). The Message of Romans"]),
   ("opp", "rebuttal", "marcus_bell", "Agreed that infant studies can't settle this. My concern is that the language of 'fundamentally sinful' can slide from describing our condition to describing our identity. Paul says 'such were some of you ... but you were washed' (1 Corinthians 6:11); the believer is also described as a new creation (2 Corinthians 5:17). A pastoral danger of overemphasizing depravity is that people hear their identity as shame rather than dignity needing rescue.", [(45, 6, 11, None), (46, 5, 17, None)], ["Plantinga, C. (1995). Not the Way It's Supposed to Be"]),
  ]),
 dict(title="Can psychology and Christianity be reconciled?", cat="psychology",
  question="Is it coherent for Christians to draw on the modern psychological sciences, or do the two rest on incompatible assumptions about persons?",
  summary="Christians have taken positions ranging from rejection of psychology as a rival worldview to full integration of research and theology.",
  aff="Reconcilable", opp="Fundamentally in tension",
  aff_sum="Psychological research studies the creation God made; its findings can be received with discernment alongside Scripture, much as medicine or physics can.",
  opp_sum="Psychological theories carry worldview assumptions about human nature that conflict with Scripture, so Christian counseling should be grounded in the Bible rather than in psychology.",
  entries=[
   ("aff", "opening", "eleanor_vance", "Christians have long drawn on knowledge from outside the Bible, in medicine, agriculture and engineering. Psychology is a field with strong empirical methods in some areas (for example the evidence for exposure-based treatments for anxiety) and speculative theory in others. The task is discernment: receive well-supported findings with gratitude (Proverbs 25:2 speaks of the glory of searching out matters), and evaluate theories for the worldview assumptions they bring. The 'integration' model in Johnson's Five Views volume describes several careful ways of doing exactly that.", [(19, 25, 2, None), (51, 5, 21, 22)], ["Johnson, E. L. (ed.) (2010). Psychology & Christianity: Five Views, 2nd ed., IVP Academic", "Pargament, K. (1997). The Psychology of Religion and Coping"]),
   ("opp", "opening", "david_okafor", "I am sympathetic to caution, and I'll argue for the strongest version of it. Many major psychological systems were built by thinkers who rejected or ignored the Christian doctrines of sin, grace and redemption, and their theories of human motivation reflect that. Jay Adams argued in Competent to Counsel that Scripture is sufficient for the nouthetic counselor's work. Whatever one thinks of his conclusions, the underlying concern deserves a hearing: if our basic model of the person comes from secular theory, Scripture may be reduced to a supplement. Colossians 2:8 warns about philosophies that are 'according to human tradition' rather than Christ.", [(50, 2, 8, None), (54, 3, 16, 17), (60, 1, 3, None)], ["Adams, J. (1970). Competent to Counsel", "Powlison, D. (2003). Seeing with New Eyes"]),
   ("aff", "rebuttal", "eleanor_vance", "The sufficiency of Scripture, as classically understood, concerns what is needed for salvation and godliness, not that Scripture contains everything we may learn about the world. Nobody concludes from 2 Timothy 3:16-17 that we shouldn't set a broken arm. The risk the opposing side names is real, and good integrationists address it by distinguishing data (replicated findings) from interpretation (worldview-laden theory). Treating some conditions as at least partly biological and treatable is not a denial of Scripture's authority.", [(54, 3, 16, 17)], ["Jones, S. & Butman, R. (2011). Modern Psychotherapies, 2nd ed."]),
   ("opp", "rebuttal", "david_okafor", "A fair clarification. I would say my concern is about the foundation, not the toolbox: I have no objection to a Christian using a cognitive-behavioral technique, if it is judged by Scripture and not the other way around. Where I want to push back is the assumption that the two sides of the 'integration' project are equal partners. If they are not, we should say which one wins when they conflict. I think that is the real argument.", [], ["Powlison, D. (2010). The Biblical Counseling Movement"]),
  ]),
 dict(title="Is morality dependent on God?", cat="philosophy",
  question="Does objective morality require God as its source, or can ethics stand on its own foundations?",
  summary="This debate has roots in Plato's Euthyphro dilemma. Both theists and non-theists have offered serious accounts.",
  aff="Morality depends on God", opp="Morality is independent of God",
  aff_sum="Objective moral facts, duties and human dignity are best explained by a necessarily good God, who is the standard of goodness and the source of obligation.",
  opp_sum="Moral truths hold independently of any divine will; whatever one thinks of God's existence, ethics can be grounded in reason, human flourishing, or moral facts.",
  entries=[
   ("aff", "opening", "thomas_ashby", "The question is not whether atheists can be moral; they plainly can. It's about what grounds morality. If there are objective moral facts that bind us regardless of opinion, we want an explanation of why they exist and why they have authority over us. Robert Adams defends a theistic account in which God is the Good itself and obligations are constituted by divine commands, from a God who is perfectly loving. That view avoids the Euthyphro dilemma by locating goodness in God's nature rather than in arbitrary will.", [(0, 1, 27, None), (44, 2, 14, 15), (32, 6, 8, None)], ["Adams, R. M. (1999). Finite and Infinite Goods, Oxford UP", "Plato, Euthyphro", "Evans, C. S. (2013). God and Moral Obligation"]),
   ("opp", "opening", "sofia_marin", "Moral realists such as Russ Shafer-Landau argue that objective moral truths exist without any divine foundation, as necessary truths like those of mathematics. The Euthyphro dilemma suggests that if God commands what is good because it is good, goodness is independent of God; and if goodness is whatever God commands, it seems arbitrary. The reply that goodness is God's nature is a move rather than a resolution: we still need a reason to count God's nature as the standard. Meanwhile, moral psychology (e.g., Haidt's work) suggests moral intuitions arise from several sources, which is an explanation that does not obviously require a divine foundation.", [(44, 2, 14, 15)], ["Shafer-Landau, R. (2003). Moral Realism: A Defence", "Haidt, J. (2012). The Righteous Mind", "Garcia, R. & King, N. (eds.) (2009). Is Goodness without God Good Enough?"]),
   ("aff", "rebuttal", "thomas_ashby", "Paul in Romans 2:14-15 notes that those without the law know it by conscience, which implies that moral knowledge does not require explicit belief in God. That fits the theistic view: knowing is not grounding. My claim is about the metaphysics. Moral realism without God still owes an account of why abstract truths impose obligations on persons. A necessarily good, personal God offers one; impersonal moral facts leave it a brute fact.", [(44, 2, 14, 15)], []),
   ("opp", "rebuttal", "sofia_marin", "'Brute fact' charges cut both ways: the theist's necessary being with a good nature is also, in the end, where explanation stops. Whether one terminus is more satisfying than the other is a judgment call. I'd suggest the more modest conclusion that theism offers one coherent account of morality, which many find compelling, not the only one.", [], ["Wielenberg, E. (2014). Robust Ethics"]),
  ]),
 dict(title="What happens to consciousness after death?", cat="mind-soul",
  question="Does the person continue consciously between death and resurrection, or is the intermediate state best understood as sleep or non-existence until resurrection?",
  summary="Christian views of the intermediate state vary, and they connect to deep questions about the soul, the body and the nature of consciousness.",
  aff="Conscious existence continues", opp="No conscious existence until resurrection",
  aff_sum="The person continues consciously after death in the presence of God, as the New Testament's language of 'being with Christ' suggests, awaiting bodily resurrection.",
  opp_sum="Persons are fundamentally embodied, and Scripture speaks of the dead as sleeping; hope rests on resurrection, not on a disembodied survival.",
  entries=[
   ("aff", "opening", "thomas_ashby", "Jesus tells the thief on the cross, 'Today you will be with me in Paradise' (Luke 23:43). Paul says he desires 'to depart and be with Christ, which is far better' (Philippians 1:23) and prefers to be 'away from the body and at home with the Lord' (2 Corinthians 5:8). Those texts most naturally imply conscious presence with Christ between death and resurrection. The tradition from Augustine and Aquinas to the Westminster Confession (ch. 32) affirms an intermediate state in which the soul continues to exist, awaiting the resurrection of the body.", [(41, 23, 43, None), (49, 1, 21, 24), (46, 5, 6, 8), (65, 6, 9, 11)], ["Westminster Confession of Faith, ch. 32", "Cooper, J. W. (1989). Body, Soul, and Life Everlasting"]),
   ("opp", "opening", "rachel_kim", "The New Testament consistently describes death as 'sleep' (1 Thessalonians 4:13-14; John 11:11) and fixes hope on resurrection, not on a soul's escape. Ecclesiastes 9:5 says 'the dead know nothing.' Oscar Cullmann argued that the biblical hope is resurrection, in contrast to Greek immortality of the soul. Nancey Murphy's non-reductive physicalism argues that the biblical view of persons is holistic and that Christians can affirm that God will re-create us at the resurrection, with continuity preserved in God's memory and power. Luke 23:43 can be read with a comma after 'today', stressing when the promise is made.", [(51, 4, 13, 14), (42, 11, 11, None), (20, 9, 5, None)], ["Cullmann, O. (1958). Immortality of the Soul or Resurrection of the Dead?", "Murphy, N. (2006). Bodies and Souls, or Spirited Bodies?"]),
   ("aff", "rebuttal", "thomas_ashby", "The comma reading is a minority proposal and it would be unusual in Luke, where 'today' regularly emphasizes the present fulfillment (e.g., Luke 19:9). And Philippians 1:23 sets 'departing and being with Christ' against remaining in the flesh as a better option, which loses its force if the interval is unconscious non-existence. 'Sleep' is a euphemism for how death looks from our side, and does not state a metaphysical claim about the person's condition.", [(41, 19, 9, None), (49, 1, 23, None)], []),
   ("opp", "rebuttal", "rachel_kim", "If subjective experience of an interval is absent, then Paul's 'departing' would be experienced as immediate transition to resurrection life, which makes the 'far better' language fit as well. The key point is that Paul's own emphasis falls on the resurrection of the body (1 Corinthians 15), and a view that makes the disembodied state the climax of hope would be foreign to him.", [(45, 15, 51, 55)], []),
   ("aff", "counter", "amara_lindqvist", "A note on 'near-death experience' evidence, which sometimes enters this topic. Studies such as the AWARE study (Parnia et al., 2014) examined reports of experiences during cardiac arrest and found these were relatively rare and no verified instance of the visual awareness tested. The research is useful for understanding what people experience; it doesn't support either side's theological claims, and it would be unwise to cite it as though it did.", [], ["Parnia, S. et al. (2014). Resuscitation 85(12)", "Chalmers, D. (1995). Journal of Consciousness Studies 2(3)"]),
  ]),
 dict(title="Is anxiety primarily psychological, spiritual, or both?", cat="faith-mental-health",
  question="How should Christians understand anxiety: as a condition to be treated, a spiritual struggle to be addressed, or an interplay of both?",
  summary="Anxiety disorders are common. Christians disagree about how much weight to give clinical, spiritual and relational explanations. This debate is about understanding, not about replacing care.",
  aff="Both psychological and spiritual", opp="Primarily one domain",
  aff_sum="Anxiety is a whole-person phenomenon, with biological, psychological, relational and spiritual dimensions, best addressed by integrating treatment, community and prayer.",
  opp_sum="Common explanations obscure important distinctions; anxiety disorders are best understood primarily as health conditions, and spiritual framings risk guilt and delay in seeking care.",
  entries=[
   ("aff", "opening", "david_okafor", "Scripture treats people as embodied and spiritual at once. Elijah in 1 Kings 19 is exhausted, frightened and discouraged; God responds with sleep and food before conversation. That's a model for care that attends to the body as well as the soul. Philippians 4:6-7 and 1 Peter 5:7 invite us to bring anxieties to God, which is consistent with, not opposed to, seeking professional treatment. Religious coping research (Pargament) finds that religion can help or harm depending on how it is used, which shows why both the spiritual and psychological dimensions matter.", [(10, 19, 3, 8), (49, 4, 6, 7), (59, 5, 7, None)], ["Pargament, K. (1997). The Psychology of Religion and Coping", "Koenig, H. (2012). ISRN Psychiatry, 'Religion, Spirituality, and Health'"]),
   ("opp", "opening", "eleanor_vance", "I'll argue for the narrower claim that, as a matter of explanation, anxiety disorders are primarily health conditions. They show familial patterns, respond to specific treatments (CBT, certain medications), and are common: in a large US survey, roughly a quarter of respondents met criteria for an anxiety disorder at some point in life (Kessler et al., 2005). Treating a disorder as a moral or spiritual failing delays care and often adds shame. I do think spiritual resources are valuable for many people, but we should be clear that religious practice is a support, not the explanation or cure, and the research on religion and health is mixed in quality.", [(39, 6, 25, 34)], ["Kessler, R. et al. (2005). Archives of General Psychiatry 62(6)", "Hofmann, S. et al. (2012). Cognitive Therapy and Research 36", "Koenig (2012), cited above"]),
   ("aff", "rebuttal", "david_okafor", "I agree that blaming people for their anxiety is harmful and wrong. But 'primarily' a health condition still leaves out what a person's fear is about. People ask 'Will I be safe? Do I matter? Who holds my life?' Those are spiritual questions whatever the underlying neurobiology. A good clinician and a good pastor will often be working on the same person from different directions, and the two should talk to each other.", [], []),
   ("opp", "rebuttal", "eleanor_vance", "I accept that. My concern was about what we claim as cause and what we prescribe first. If your framing leads a person to see a doctor and also to pray, I have no objection. If it leads them to treat illness as a lack of faith, I do. So we may agree on practice and differ only on emphasis.", [], []),
  ]),
]

# Library: type, category, title, author, label, tags, minutes, summary, body
ARTICLES = [
 ("article", "theology", "The Image of God: Three Ways Theologians Have Read Genesis 1:27", "Rachel Kim", "theology", "image-of-god,anthropology", 7,
  "A survey of structural, relational and functional readings of the imago Dei, and what each implies for human dignity.",
  "## Why the question matters\nGenesis 1:27 says that humanity is created 'in the image of God'. The phrase appears only briefly in the Old Testament, yet it has shaped Christian thinking about human dignity, ethics and the nature of persons more than almost any other.\n\n## The structural view\nThe structural reading locates the image in a capacity: reason, will, moral awareness. Augustine and Aquinas explored the soul's rational powers as the place where humanity most resembles God. The strength of this view is that it explains how humans can reflect God's knowing and choosing. Its weakness is that it can seem to exclude people with cognitive disabilities, which most theologians regard as a serious problem.\n\n## The relational view\nKarl Barth stressed that the image is not a possession but a relation: humans are created male and female, for fellowship with each other and with God. On this view, persons image God by being in communion. The relational view guards against reducing the image to intellect, though critics ask whether it makes the image dependent on actually standing in relationships.\n\n## The functional view\nMany Old Testament scholars note that in the ancient Near East, kings placed statues of themselves to represent their rule. Genesis 1 applies the language to all humans: they are God's representatives, charged with caring for creation. The functional view fits the context of Genesis 1:26-28. Questions remain about what happens to the image when a person cannot carry out the function.\n\n## Putting them together\nMost contemporary theologians combine the three: the image involves what we are (capacities), how we are (in relationship) and what we are for (representation). Whatever view one holds, the New Testament teaches that Christ is the true image (Colossians 1:15), and that believers are being renewed in it (Colossians 3:10). The doctrine has practical consequences: it grounds the dignity of every person, regardless of ability, productivity or symptoms."),
 ("article", "psychology", "Cognitive Behavioral Therapy: What It Is and What the Evidence Says", "Dr. Eleanor Vance", "research", "cognitive,behavioral,mental-health", 8,
  "An accessible overview of CBT, its theoretical roots, and how well it works for anxiety and depression.",
  "## The basic idea\nCognitive behavioral therapy (CBT) grew out of two streams: behaviorism, which studies how learning shapes action, and cognitive psychology, which studies how interpretation shapes emotion. Aaron Beck, working in the 1960s and 70s, observed that depressed patients held automatic negative thoughts about themselves, the world and the future. He proposed that examining and testing those thoughts could change mood.\n\n## What happens in therapy\nA typical course involves a structured set of sessions. The therapist and client identify unhelpful patterns of thinking, test them against evidence, and run behavioral experiments. For anxiety, this often includes gradual exposure to feared situations; for depression, it includes behavioral activation, which means scheduling meaningful activity even when motivation is low.\n\n## What the evidence shows\nCBT is among the most studied psychological treatments. Meta-analyses find it effective for many people with anxiety disorders, depression and other conditions, with effect sizes that vary by condition and study quality (Hofmann et al., 2012). It is not a cure for everyone: some people do not respond, and benefits are not always maintained without ongoing practice.\n\n## A note on worldview\nCBT's techniques are largely neutral about ultimate beliefs, but its model carries assumptions, such as the view that rational examination of one's beliefs is generally helpful. Christian clinicians have developed adaptations that incorporate prayer and Scripture for clients who want them, and some trials suggest they are at least as effective as standard CBT for religious clients. As with any therapy, it works best with a trained clinician and a good fit between therapist and client.\n\nThis article summarizes research for educational purposes. It is not a substitute for professional care."),
 ("essay", "philosophy", "Athens and Jerusalem Revisited", "Sofia Marin", "philosophy", "philosophy-of-religion", 6,
  "Tertullian asked what Athens has to do with Jerusalem. An essay on why the answer is neither 'nothing' nor 'everything'.",
  "Tertullian's famous question was a challenge to the idea that philosophy could provide the foundations of Christian belief. Yet the church fathers who followed him found it impossible to think about the faith without borrowing from Greek thought: Justin Martyr read Plato as a kind of preparation, Augustine described the Platonists as having glimpsed things that Christianity reveals more fully, and Aquinas rebuilt the whole project around Aristotle.\n\nThe borrowing was not always wise. Greek ideas about the soul's escape from the body, for example, sit uneasily with the biblical hope of resurrection. But the alternative, a theology without philosophical tools, is not really possible. Everyone brings assumptions about causation, identity and truth. The only question is whether those assumptions are examined.\n\nPaul's speech at the Areopagus (Acts 17) shows a middle path. He quotes the poets Epimenides and Aratus, appeals to what his hearers already know about the divine, and then calls them to a message that stretches beyond what their philosophy offered. He uses Athens, and he does not stop at Athens.\n\nThis suggests a posture for those who study both faith and philosophy: receive what is true wherever it is found, test it, and be willing to correct inherited ideas when Scripture requires it. Athens is a partner, but not the final authority."),
 ("research", "psychology", "Memory Is Reconstructive: A Summary of What We Know", "Dr. Amara Lindqvist", "research", "memory,cognitive", 6,
  "How memory works, what the misinformation research shows, and why both 'memory is perfect' and 'memory is worthless' are mistakes.",
  "## A short history\nFrederic Bartlett's 1932 experiments on retelling folk stories showed that people reshape what they remember to fit their expectations. Decades later, Elizabeth Loftus and colleagues demonstrated that the wording of questions or the introduction of misleading information after an event can alter what people report, in some cases leading them to report things that did not happen.\n\n## Two models\nA useful picture is that remembering is an act of reconstruction: we draw on stored fragments and fill gaps using general knowledge. This is generally efficient and usually adequate. It is also why details can be altered and why confidence is not a reliable indicator of accuracy.\n\n## Limits of the findings\nThe laboratory findings do not show that all memory is unreliable. Central, emotionally significant events are typically remembered better than peripheral details, although errors occur. Memory research also shows that repeated recall within a community can preserve information well, especially when it is practiced in structured ways.\n\n## Why this matters beyond the lab\nThe research has influenced how courts treat eyewitness testimony and how therapists avoid suggestive questioning. When people discuss the application of memory research to ancient texts, they are making an extrapolation, and it should be flagged as such: the research can inform plausibility, but does not directly verify or discredit particular historical claims."),
 ("biblical", "biblical-interpretation", "Reading Psalms: Genre, Poetry and Lament", "Jonathan Reeve", "theology", "psalms,hermeneutics", 7,
  "How to read the Psalms on their own terms: Hebrew parallelism, the major genres, and why so many are complaints.",
  "## Poetry, not propositions\nThe Psalms are Hebrew poetry, and the central feature of that poetry is parallelism: a second line that echoes, intensifies or contrasts with the first. Psalm 19:1 says 'The heavens declare the glory of God, and the sky above proclaims his handiwork.' The second line is not a new fact but a re-saying that deepens the first. Recognizing this prevents us from over-analyzing each phrase.\n\n## Major types\nScholars since Hermann Gunkel have sorted psalms by type: hymns of praise, thanksgiving songs, wisdom psalms, royal psalms and laments. Laments are the largest group. They typically include an address to God, a complaint, a request, and (often) an expression of trust or a vow of praise.\n\n## Why laments matter\nLaments teach that honest anguish belongs in worship. Psalm 88 is the starkest example: it ends in darkness, with no resolution. The fact that the canon includes it tells us that faith is not always expressed in cheerful words.\n\n## Reading them in Christ\nThe New Testament quotes the Psalms more than any other Old Testament book. Jesus cried out Psalm 22:1 from the cross. Reading the Psalms through Christ does not erase their original setting; it shows how the church found in them the voice of both the suffering king and his people."),
 ("essay", "faith-mental-health", "When Prayer and Treatment Work Together", "David Okafor", "discussion", "mental-health,pastoral", 5,
  "A pastor's reflection on holding spiritual care and clinical care together without competing.",
  "In my first years as a pastor I sometimes did harm without meaning to. A woman in our congregation described waking up every night with her heart racing. I told her to pray and trust God, and she left feeling both anxious and ashamed. Months later she told me she had finally seen a doctor, and that she was ashamed she had waited.\n\nI have since learned to hold two commitments together. First, the people who come to me are whole persons, and prayer, scripture and community matter to them. Second, I am not a clinician. When someone describes persistent panic, long depression, or thoughts of harming themselves, my job includes helping them find qualified care and staying with them while they do.\n\nThese commitments are not rivals. When Elijah collapsed in the wilderness in 1 Kings 19, God sent food and rest before speaking. Physical care and spiritual care came together. I now think of prayer and treatment as allies: one does not need to compete for the credit.\n\nA word to pastors: learn the local clinicians you can refer to, and ask them what they wish pastors knew. A word to clinicians: ask your religious clients what their faith means to them, and do not assume it is either a resource or a problem. A word to anyone struggling: asking for help is not a failure of faith."),
 ("research", "psychology", "Religion and Health: Reading the Research Carefully", "Dr. Eleanor Vance", "research", "mental-health,research-methods", 7,
  "A guide to what studies of religious involvement and wellbeing show, and the cautions we need in interpreting them.",
  "## What the studies tend to find\nLarge reviews, including Harold Koenig's 2012 summary, report that religious involvement is associated, on average, with better outcomes on measures such as depression, social support and some health behaviors. These are associations in observational studies, and the strength varies by population and measure.\n\n## Cautions\nFirst, correlation is not causation. People who are healthier may find it easier to attend services, and religious communities provide social support that may account for part of the effect. Second, 'religion' is a broad category: attendance, private prayer, religious coping style and belief intensity are different variables and can have different relationships to outcomes. Pargament's research distinguishes positive religious coping (collaborative, supportive) from negative religious coping (e.g., viewing struggles as divine punishment), with the latter associated with poorer outcomes. Third, the literature has been affected by the same issues as other social-science research, including publication bias and measurement problems.\n\n## What we can responsibly say\nFor many people, religious communities and practices are a source of meaning and support. But it would be inappropriate to present religion as a treatment, or to suggest that struggles with mental health indicate lack of faith. The research cannot tell us whether Christianity is true, and the truth of Christianity does not depend on a health benefit."),
 ("biblical", "biblical-interpretation", "Nephesh, Psyche and the Biblical Language of the Soul", "Jonathan Reeve", "theology", "soul,anthropology,hebrew,greek", 8,
  "What the Hebrew nephesh and the Greek psyche meant in their contexts, and why this matters for discussions of soul and body.",
  "## Nephesh in the Old Testament\nThe Hebrew word nephesh occurs more than 750 times in the Old Testament and is often translated 'soul'. But its range is wide: in Genesis 2:7 God breathes into the man and he becomes a nephesh chayyah, a 'living being'. It can refer to a person (Genesis 12:5), to appetite (Proverbs 23:2) or to life itself (Leviticus 17:11). The word rarely refers to a separable immaterial part. Many scholars conclude that the Hebrew view of the person is holistic: the human is a living, embodied being, not a spirit inhabiting a body.\n\n## Psyche in Greek thought and the New Testament\nIn classical Greek philosophy, especially in the Platonic tradition, the psyche is often the rational, immortal part of a person. The New Testament uses psyche in a way closer to the Hebrew: it can mean life (Mark 8:35) or the self (Acts 2:41). At the same time, passages such as Matthew 10:28 ('do not fear those who kill the body but cannot kill the soul') and Revelation 6:9 have led many interpreters to find that the soul can exist apart from the body, at least temporarily.\n\n## What follows?\nThese word studies do not settle the metaphysics. They remind us that the debate between dualist and physicalist positions cannot be won by quoting 'soul' verses alone. The more productive question is how the whole biblical picture, of creation, death, intermediate state and resurrection, fits together. Both camps have serious answers."),
 ("article", "theology", "Providence and Human Freedom: A Short Map of the Debate", "Rachel Kim", "theology", "free-will,providence", 6,
  "A map of the main Christian positions (Calvinist, Arminian, Molinist, open theist) on how God governs a world of free creatures.",
  "Most Christians agree on two points: God governs all things, and human beings are responsible for what they do. The disagreements come over how those claims relate.\n\n**Calvinist (Reformed).** God ordains whatever comes to pass, and human freedom is defined as acting according to one's own desires. This is called compatibilism. The Westminster Confession says God ordains all things, yet 'neither is God the author of sin, nor is violence offered to the will of the creatures.'\n\n**Arminian.** God gives creatures libertarian freedom: the real power of contrary choice. God's foreknowledge is exhaustive, but it does not cause the outcome. Election is based on God's foreknowledge of faith.\n\n**Molinist.** Named for Luis de Molina, this view holds that God knows what any free creature would do in any circumstance (middle knowledge) and so can plan a world to achieve his purposes without determining free choices. William Lane Craig is a leading contemporary defender. Critics question whether such counterfactual truths could be true and known independent of God's decision.\n\n**Open theist.** Some hold that the future is partly open, and God does not know free future choices exhaustively. This is a minority view and is criticized as departing from the classical doctrine of God.\n\nNo position is free of difficulty, and each draws on large parts of Scripture. A charitable approach is to learn what each view says in its own best formulation before arguing against it."),
 ("research", "psychology", "Attachment Theory: Origins, Findings and Limits", "Dr. Eleanor Vance", "research", "relationships,developmental", 7,
  "From Bowlby and Ainsworth to adult attachment research: what is well supported and what remains debated.",
  "## Origins\nJohn Bowlby proposed in the mid-twentieth century that human infants have an evolved tendency to seek closeness to caregivers, especially when distressed. Mary Ainsworth's 'Strange Situation' procedure, developed in the 1970s, classified infants by how they responded to separation and reunion: secure, anxious-ambivalent and avoidant (a disorganized pattern was later added).\n\n## What is well supported\nThere is considerable evidence that caregiving sensitivity is associated with infant attachment security, and that attachment patterns are moderately associated with later social outcomes. Adult attachment research, beginning with Hazan and Shaver in the 1980s, has extended these ideas to romantic relationships.\n\n## Cautions\nEarly attachment is not destiny: patterns can change with later experiences. Cultural variation in caregiving means that classification systems developed in Western samples may not apply uniformly. Heritability and temperament also contribute.\n\n## Attachment and religion\nSome researchers, notably Lee Kirkpatrick, have proposed that people's relationship with God can function as an attachment relationship. Evidence for the 'correspondence' hypothesis (that images of God mirror early attachment) and the 'compensation' hypothesis (that insecurely attached people turn to God as a substitute) is mixed. This area illustrates why we should distinguish reliable findings, theoretical proposals and theological claims: the theology of God as Father does not depend on any psychological theory."),
 ("essay", "mind-soul", "Hylomorphism for the Modern Reader", "Sofia Marin", "philosophy", "soul,philosophy-of-mind", 6,
  "Aquinas's view that the soul is the form of the body offers a third option between 'ghost in the machine' and reductive materialism.",
  "Descartes's picture of the mind as an immaterial substance joined to a material body has dominated popular debates about the soul. But it is not the only Christian view, and it was not Aquinas's.\n\nFollowing Aristotle, Aquinas held that a living thing is a unity of matter and form. The soul is the form of the body: the organizing principle that makes this matter a human being. The soul is not a separate thing that happens to live in a body. A human is one substance, and the soul and body are principles of that one being.\n\nThis view has interesting consequences. It takes embodiment seriously and avoids the interaction problem that troubles Cartesian dualists. It can also explain the correlation between brain states and mental states without implying that the mind is merely the brain. Aquinas also held that the rational soul can survive death in a diminished state awaiting the resurrection, which makes his view a form of moderate dualism.\n\nPhilosophers disagree about whether hylomorphism can be defended in light of modern science, and about what it implies for questions such as personal identity. But it is a reminder that the options in Christian thought about the soul are richer than a choice between Descartes and materialism."),
 ("apologetics", "apologetics", "How to Disagree Well: A Field Guide for Apologetic Conversations", "Thomas Ashby", "discussion", "apologetics,conversation", 5,
  "Practical principles for conversations about hard questions: listen first, state the other view fairly, and know the limits of your argument.",
  "I was not argued into faith. I was asked questions by people who seemed to care what I thought. That experience shaped how I approach apologetics.\n\n**1. Listen until you can state the question in the other person's words.** Many conversations fail because we answer a question that was not asked. Someone who says 'How can a good God allow suffering?' may be asking an intellectual question, or may be in pain. These need different responses.\n\n**2. Make the strongest version of the other view before responding.** If a skeptic could not recognize their view in your summary, you are not yet answering it.\n\n**3. Distinguish what you know from what you hope.** Some claims in an argument are well supported, some are plausible, some are speculation. Say which is which. 1 Peter 3:15 asks for a reason for our hope 'with gentleness and respect'.\n\n**4. Know the limits of arguments.** Arguments can remove obstacles and show that faith is reasonable; they do not replace the work of God in a person's life or a person's own freedom.\n\n**5. Be willing to say 'I don't know' and 'good point'.** This is not a sign of weakness. It is how people learn that you are being honest."),
 ("research", "psychology", "Emotion Regulation: Reappraisal, Suppression and the Practice of Lament", "Dr. Amara Lindqvist", "research", "emotions,mental-health", 6,
  "What the emotion regulation literature says about reappraisal and suppression, and how it relates to spiritual practices.",
  "James Gross's process model of emotion regulation distinguishes strategies by when they act. Reappraisal, reinterpreting the meaning of a situation, acts early. Suppression, inhibiting the outward expression of emotion, acts late. In laboratory studies and surveys, habitual reappraisal tends to be associated with better wellbeing, while habitual suppression is associated with poorer outcomes and social costs, although the findings depend on context and culture.\n\nThese are general tendencies, not rules. In some situations suppression is adaptive, and reappraisal is not always possible. There are also questions about how well laboratory tasks capture everyday regulation.\n\nSome have connected these findings to the practice of lament and prayer. The biblical laments do not suppress; they express distress to God directly and often shift, as in Psalm 13, toward trust. Whether this is best understood as a form of reappraisal is a theoretical interpretation, not an established finding. What the research can say is that acknowledging emotion rather than suppressing it is generally associated with better outcomes, and that practices which provide a safe context to express emotion may help."),
 ("book", "theology", "Confessions", "Augustine of Hippo", "theology", "augustine,classic", 0,
  "Augustine's autobiography-as-prayer, written around 397-400, and one of the most psychologically perceptive works of the ancient world.",
  "Augustine tells the story of his restless youth, his years as a teacher of rhetoric, his time with the Manichaeans and his conversion, all addressed directly to God. The famous line, 'Our heart is restless until it rests in you', summarizes the book's theme.\n\nWhy read it: it is a classic of Christian spirituality and also an early exploration of memory (Book X), time (Book XI) and the divided will (Book VIII). Readers interested in how theology and psychology touch will find a long-standing conversation here.\n\nSuggested edition: any modern translation (Henry Chadwick's for Oxford World's Classics is a clear choice)."),
 ("book", "psychology", "Thinking, Fast and Slow", "Daniel Kahneman", "research", "cognitive,decision-making", 0,
  "A readable overview of decades of research on judgment and decision-making, including heuristics and biases.",
  "Kahneman describes two modes of thinking: a fast, intuitive mode and a slower, effortful mode. The book draws on his work with Amos Tversky on heuristics and biases, including prospect theory.\n\nHow to read it: as an excellent account of a research program. Some of the studies cited from social priming have not replicated well, and Kahneman himself acknowledged this. It is a good example of why it helps to follow research as it develops."),
 ("book", "mind-soul", "Bodies and Souls, or Spirited Bodies?", "Nancey Murphy", "theory", "soul,nonreductive-physicalism", 0,
  "A philosopher-theologian's case for non-reductive physicalism, written for readers interested in neuroscience and Christian anthropology.",
  "Murphy argues that the human person need not be understood as a composite of body and immaterial soul in order to preserve what is important to Christianity: moral responsibility, relationship with God and hope for resurrection.\n\nHow to read it: as one serious position among several. Readers who favor dualism will find well-argued objections to engage; readers inclined toward physicalism will find a Christian development of their view."),
 ("book", "psychology", "Psychology & Christianity: Five Views", "Eric L. Johnson (ed.)", "discussion", "integration,counseling", 0,
  "Five scholars present competing models for relating psychology and Christian faith, with responses to each other.",
  "The five approaches are Levels-of-Explanation, Integration, Christian Psychology, Transformational Psychology and Biblical Counseling. Each contributor presents their view and responds to the others.\n\nHow to read it: as a map of the territory. It pairs well with the debate here on whether psychology and Christianity can be reconciled."),
 ("book", "apologetics", "Orthodoxy", "G. K. Chesterton", "discussion", "apologetics,classic", 0,
  "A 1908 spiritual autobiography in argument: Chesterton explains why he found Christian orthodoxy to be a more adventurous and humane account of the world than the alternatives.",
  "Chesterton's style is playful and paradoxical. Whether or not one agrees with his conclusions, the book is notable for its attempt to describe belief as an experience of discovery rather than inherited rule.\n\nHow to read it: for its imagination and wit. Treat its historical generalizations with the caution appropriate to a work written as essay rather than history."),
]

